<script setup>
import { computed, onMounted, ref } from 'vue'
import ListView from '../shared/components/ListView.vue'
import { fromMinorUnits, toMinorUnits } from './consultationPricing.js'

const props = defineProps({ token: { type: String, required: true }, locale: { type: String, default: 'es' } })
const isEnglish = computed(() => props.locale === 'en')
const t = (es, en) => isEnglish.value ? en : es
const errorText = (message) => isEnglish.value
  ? t('No se pudo completar la operación. Inténtalo de nuevo.', 'The operation could not be completed. Please try again.')
  : (message || 'No se pudo completar la operación. Inténtalo de nuevo.')
const loading = ref(true); const saving = ref(false); const error = ref(''); const notice = ref('')
const catalog = ref({ services: [], consultationTypes: [], experts: [], allExperts: [] })
const formOpen = ref(false); const editingId = ref('')
const form = ref({ code: '', name: '', description: '', serviceCode: '', amount: 0, currency: 'USD', paymentRequired: true, active: true, expertIds: [] })
const consultations = computed(() => catalog.value.consultationTypes || [])
const assignedExperts = computed(() => catalog.value.experts || [])

async function request(url, options = {}) { const response = await fetch(url, { ...options, headers: { Authorization: `Bearer ${props.token}`, ...(options.headers || {}) } }); const data = await response.json().catch(() => ({})); if (!response.ok) throw new Error(errorText(data.error)); return data }
async function load() { loading.value = true; error.value = ''; try { catalog.value = await request('/api/app/catalog') } catch (loadError) { error.value = errorText(loadError.message) } finally { loading.value = false } }
function openNew() { editingId.value = ''; form.value = { code: '', name: '', description: '', serviceCode: catalog.value.services[0]?.code || '', amount: 0, currency: 'USD', paymentRequired: true, active: true, expertIds: [] }; formOpen.value = true }
function edit(item) { const service = catalog.value.services.find((candidate) => candidate.consultations?.some((consultation) => consultation.consultationId === item.id)); const linked = assignedExperts.value.filter((expert) => expert.consultationTypeId === item.id).map((expert) => expert.id); const price = service?.consultations?.find((consultation) => consultation.consultationId === item.id); form.value = { code: item.code, name: item.name, description: item.description || '', serviceCode: service?.code || '', amount: fromMinorUnits(price?.amountCents), currency: price?.currency || 'USD', paymentRequired: true, active: item.active, expertIds: linked }; editingId.value = item.id; formOpen.value = true }
function cancel() { formOpen.value = false; editingId.value = '' }
async function save() { saving.value = true; error.value = ''; notice.value = ''; try { const payload = { ...form.value, amountCents: toMinorUnits(form.value.amount) }; delete payload.amount; await request(editingId.value ? `/api/app/catalog/consultation-types/${editingId.value}` : '/api/app/catalog/consultation-types', { method: editingId.value ? 'PUT' : 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) }); notice.value = t('Tipo de consulta guardado correctamente.', 'Consultation type saved successfully.'); cancel(); await load() } catch (saveError) { error.value = errorText(saveError.message) } finally { saving.value = false } }
function money(cents, currency) { return new Intl.NumberFormat(isEnglish.value ? 'en-US' : 'es-CO', { style: 'currency', currency, maximumFractionDigits: currency === 'USD' ? 2 : 0 }).format(Number(cents || 0) / 100) }
onMounted(load)
</script>

<template>
  <section class="module-view catalog-view"><div class="module-heading"><div><p class="eyebrow">{{ t('Configuración operativa', 'Operations settings') }}</p><h1>{{ t('Servicios y consultas', 'Services and consultations') }}</h1><p>{{ t('Administra la oferta comercial, sus precios y los expertos asignados.', 'Manage the service offering, prices, and assigned experts.') }}</p></div><div class="module-heading-actions"><button type="button" class="primary-button compact" @click="openNew">{{ t('+ Nueva consulta', '+ New consultation') }}</button><button type="button" class="secondary-button compact" @click="load">↻ {{ t('Actualizar', 'Refresh') }}</button></div></div><p v-if="notice" class="security-notice">{{ notice }}</p><p v-if="error" class="request-error">{{ error }}</p><div v-if="loading" class="module-state panel">{{ t('Cargando catálogo…', 'Loading catalog…') }}</div><template v-else>
    <form v-if="formOpen" class="panel catalog-editor-form" @submit.prevent="save"><div class="panel-heading"><div><h2>{{ editingId ? t('Editar tipo de consulta', 'Edit consultation type') : t('Nueva consulta', 'New consultation') }}</h2><p>{{ t('Define el servicio general, precio, descripción y expertos.', 'Set the general service, price, description, and experts.') }}</p></div><button type="button" class="secondary-button compact" @click="cancel">{{ t('Cancelar', 'Cancel') }}</button></div><div class="catalog-form-grid"><label>{{ t('Código', 'Code') }}<input v-model="form.code" :disabled="Boolean(editingId)" pattern="[a-z][a-z0-9_-]{2,50}" placeholder="consulta_basica" required /></label><label>{{ t('Servicio general', 'General service') }}<select v-model="form.serviceCode" required><option value="" disabled>{{ t('Selecciona un servicio', 'Select a service') }}</option><option v-for="service in catalog.services" :key="service.id" :value="service.code">{{ service.name }}</option></select></label><label>{{ t('Nombre', 'Name') }}<input v-model="form.name" :placeholder="t('Consulta básica', 'Basic consultation')" required /></label><label>{{ t('Precio', 'Price') }}<input v-model.number="form.amount" type="number" min="0" step="0.01" required /></label><label>{{ t('Moneda', 'Currency') }}<select v-model="form.currency"><option value="USD">USD</option><option value="COP">COP</option></select></label><label class="full-label">{{ t('Descripción', 'Description') }}<textarea v-model="form.description" rows="3" :placeholder="t('Describe qué incluye la consulta.', 'Describe what the consultation includes.')" required></textarea></label></div><fieldset class="permission-picker"><legend>{{ t('Expertos asociados', 'Assigned experts') }}</legend><label v-for="expert in catalog.allExperts" :key="expert.id" class="permission-option"><input v-model="form.expertIds" type="checkbox" :value="expert.id" /><span><strong>{{ expert.name }}</strong><small>{{ expert.email }}</small></span></label><small v-if="!catalog.allExperts?.length" class="empty-inline">{{ t('Primero crea usuarios con rol Experto.', 'Create users with the Expert role first.') }}</small></fieldset><div class="form-actions"><button type="button" class="secondary-button compact" @click="cancel">{{ t('Cancelar', 'Cancel') }}</button><button type="submit" class="primary-button" :disabled="saving">{{ saving ? t('Guardando…', 'Saving…') : t('Guardar consulta', 'Save consultation') }} <span>→</span></button></div></form>
    <ListView :title="t('Tipos de consulta', 'Consultation types')" :description="t('Servicios vendibles con precio y expertos responsables.', 'Services available for purchase, with pricing and assigned experts.')" :count="consultations.length" :page="1" :total-pages="1" :empty="!consultations.length" :empty-text="t('No hay tipos de consulta configurados.', 'No consultation types are configured.')" :locale="locale"><template #columns><th>{{ t('Consulta', 'Consultation') }}</th><th>{{ t('Servicio general', 'General service') }}</th><th>{{ t('Precio', 'Price') }}</th><th>{{ t('Expertos', 'Experts') }}</th><th>{{ t('Estado', 'Status') }}</th><th>{{ t('Acciones', 'Actions') }}</th></template><template #rows><tr v-for="item in consultations" :key="item.id"><td><strong>{{ item.name }}</strong><br /><span class="muted-cell">{{ item.description }}</span></td><td>{{ catalog.services.find((service) => service.consultations?.some((consultation) => consultation.consultationId === item.id))?.name || '—' }}</td><td>{{ money(catalog.services.flatMap((service) => service.consultations || []).find((consultation) => consultation.consultationId === item.id)?.amountCents, catalog.services.flatMap((service) => service.consultations || []).find((consultation) => consultation.consultationId === item.id)?.currency || 'USD') }}</td><td><span class="count-badge">{{ assignedExperts.filter((expert) => expert.consultationTypeId === item.id).length }}</span></td><td><span :class="['security-status', { inactive: !item.active }]">{{ item.active ? t('Activo', 'Active') : t('Inactivo', 'Inactive') }}</span></td><td><button type="button" class="secondary-button compact" @click="edit(item)">{{ t('Editar', 'Edit') }}</button></td></tr></template></ListView>
    <ListView :title="t('Servicios generales', 'General services')" :description="t('Clasificación principal de la operación aduanera.', 'Main classification for customs operations.')" :count="catalog.services.length" :page="1" :total-pages="1" :empty="!catalog.services.length" :empty-text="t('No hay servicios configurados.', 'No services are configured.')" :locale="locale"><template #columns><th>{{ t('Servicio', 'Service') }}</th><th>{{ t('Descripción', 'Description') }}</th><th>{{ t('Consultas', 'Consultations') }}</th><th>{{ t('Estado', 'Status') }}</th></template><template #rows><tr v-for="service in catalog.services" :key="service.id"><td><strong>{{ service.name }}</strong></td><td>{{ service.description || t('Sin descripción', 'No description') }}</td><td><span class="count-badge">{{ service.consultations?.length || 0 }}</span></td><td><span :class="['security-status', { inactive: !service.active }]">{{ service.active ? t('Activo', 'Active') : t('Inactivo', 'Inactive') }}</span></td></tr></template></ListView>
  </template></section>
</template>

<style scoped>
.catalog-editor-form{display:grid;gap:16px;margin-bottom:16px;padding:20px;border:1px solid #e5eaf0;border-radius:10px;background:#fff;box-shadow:0 4px 12px rgba(25,47,70,.025)}.catalog-form-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.catalog-form-grid label{display:grid;gap:7px;color:#526174;font-size:10px;font-weight:700}.catalog-form-grid input,.catalog-form-grid select,.catalog-form-grid textarea{min-height:38px;padding:8px 10px;border:1px solid #d8e0ea;border-radius:7px;color:#344b60;background:#fff;font-size:11px}.catalog-form-grid textarea{resize:vertical}.catalog-editor-form .permission-picker{margin:0}.form-actions{display:flex;justify-content:flex-end;gap:8px}@media(max-width:800px){.catalog-form-grid{grid-template-columns:1fr}}
</style>
